-- GERADO por scripts/gerar_seed_catalogo.py a partir de database/catalogo_testes.json.
-- Não edite à mão. Idempotente: pode ser executado mais de uma vez.
ON CONFLICT (id) DO UPDATE SET regiao = EXCLUDED.regiao, nome = EXCLUDED.nome, estrutura = EXCLUDED.estrutura, definicao = EXCLUDED.definicao, objetivo = EXCLUDED.objetivo, como_fazer = EXCLUDED.como_fazer, positivo_se = EXCLUDED.positivo_se, unidade_medida = EXCLUDED.unidade_medida, referencia = EXCLUDED.referencia;
SELECT setval(pg_get_serial_sequence('testes_catalogo', 'id'), (SELECT max(id) FROM testes_catalogo));
