INSERT INTO testes_catalogo (id, regiao, nome, estrutura, definicao, objetivo, como_fazer, positivo_se, unidade_medida, referencia) VALUES
  (1, 'Joelho', 'Lachman', 'LCA', 'O teste de Lachman é um teste clínico utilizado para avaliar a integridade e a estabilidade do ligamento cruzado anterior (LCA) do joelho. É considerado um dos principais testes para investigação de lesões do LCA, pois permite avaliar a translação anterior da tíbia em relação ao fêmur com o joelho em pequena flexão. É especialmente utilizado em casos de trauma esportivo, entorses e episódios de instabilidade do joelho.', 'Verificar a presença de instabilidade anterior do joelho, identificando alterações na contenção da tíbia proporcionada pelo LCA. O teste auxilia na investigação de rupturas parciais ou completas do ligamento cruzado anterior, principalmente após mecanismos de trauma envolvendo rotação ou mudança brusca de direção.', 'Paciente em decúbito dorsal, com o joelho relaxado e flexionado aproximadamente entre 20° e 30°. O examinador estabiliza o fêmur com uma das mãos e segura a região proximal da tíbia com a outra. Em seguida, realiza uma tração anterior da tíbia, observando a quantidade de deslocamento e a qualidade do ponto final do movimento. O resultado deve ser comparado com o membro contralateral.', 'O teste é considerado positivo quando ocorre aumento da translação anterior da tíbia em relação ao fêmur, principalmente quando comparado ao lado saudável. Também pode ser observado um ponto final amolecido ou pouco firme, além de sensação de instabilidade. Esses achados são sugestivos de lesão ou insuficiência do ligamento cruzado anterior (LCA).', NULL, NULL),
  (2, 'Joelho', 'Estresse em Valgo', 'LCM', 'O teste de estresse em Valgo é um teste clínico utilizado para avaliar principalmente a integridade do ligamento colateral medial (LCM) do joelho. O LCM contribui para a estabilidade medial da articulação, especialmente contra forças que tendem a deslocar o joelho para uma posição de valgo.', 'Avaliar a estabilidade medial do joelho e identificar sinais compatíveis com lesão ou frouxidão do LCM. O teste é utilizado principalmente após traumas que provocam uma força de valgo, como impactos na região lateral do joelho.', 'Paciente em decúbito dorsal. O examinador estabiliza a região lateral do joelho e segura a perna distalmente. Aplica-se uma força direcionada de lateral para medial, provocando o estresse em valgo. O teste pode ser realizado com o joelho em extensão e também aproximadamente entre 20° e 30° de flexão, permitindo avaliar diferentes componentes da estabilidade medial.', 'O teste é considerado positivo quando há dor na região medial do joelho, associada ou não à abertura excessiva do espaço articular medial em comparação com o membro contralateral. A presença de frouxidão aumentada pode indicar lesão do ligamento colateral medial, sendo a extensão da abertura um possível indicativo da gravidade da instabilidade.', NULL, NULL),
  (3, 'Joelho', 'Estresse em Varo', 'LCL', 'O teste de Estresse em Varo é utilizado para avaliar principalmente a integridade do ligamento colateral lateral (LCL) do joelho. Esse ligamento auxilia na estabilização da parte lateral da articulação, limitando movimentos excessivos provocados por forças em varo.', 'Verificar a estabilidade lateral do joelho e identificar sinais de lesão ou frouxidão do LCL. É especialmente utilizado após traumas que provocam uma força direcionada para o varo, podendo ocorrer em atividades esportivas ou acidentes.', 'Paciente em decúbito dorsal. O examinador estabiliza a região medial do joelho e segura a parte distal da perna. Em seguida, aplica uma força de medial para lateral, produzindo o estresse em varo. O teste pode ser realizado com o joelho em extensão e aproximadamente entre 20° e 30° de flexão, comparando-se o movimento com o membro contralateral.', 'O teste é considerado positivo quando apresenta dor na região lateral do joelho e/ou abertura excessiva do espaço articular lateral em comparação ao lado oposto. Esses achados podem indicar lesão ou insuficiência do ligamento colateral lateral, podendo também sugerir comprometimento de outras estruturas estabilizadoras laterais quando a instabilidade é significativa.', NULL, NULL),
  (4, 'Tornozelo', 'Thompson', 'Tendão de Aquiles', 'O teste de Thompson, também conhecido como teste de compressão da panturrilha, é um teste clínico utilizado para avaliar a integridade do tendão de Aquiles. O tendão de Aquiles é responsável pela transmissão da força da musculatura da panturrilha para o calcâneo, participando principalmente do movimento de flexão plantar do tornozelo. O teste é frequentemente utilizado na investigação de rupturas do tendão.', 'Verificar se o tendão de Aquiles está funcionalmente íntegro, auxiliando na identificação de rupturas completas ou significativas do tendão. É especialmente indicado quando há histórico de trauma, estalo súbito, dor intensa na região posterior do tornozelo ou dificuldade para realizar a flexão plantar.', 'Paciente em decúbito ventral, com os pés posicionados para fora da maca e os tornozelos livres. O examinador realiza uma compressão da musculatura da panturrilha, observando o movimento produzido no pé. Em condições normais, a compressão da panturrilha provoca automaticamente uma flexão plantar do tornozelo.', 'O teste é considerado positivo quando a compressão da panturrilha não produz ou produz de forma muito reduzida a flexão plantar do tornozelo. A ausência desse movimento é um forte indicativo de ruptura do tendão de Aquiles, especialmente quando associada a outros sinais clínicos.', NULL, NULL),
  (5, 'Tornozelo', 'Inclinação Talar', 'Ligamentos laterais (principalmente LCF)', 'O teste de Inclinação Talar, também conhecido como Talar Tilt Test, é um teste clínico utilizado para avaliar a estabilidade ligamentar do tornozelo. Na realização em inversão, avalia principalmente as estruturas do complexo ligamentar lateral, especialmente o ligamento calcaneofibular (LCF), podendo também envolver outras estruturas laterais dependendo da posição do tornozelo.', 'Avaliar a presença de instabilidade ligamentar lateral do tornozelo, auxiliando na investigação de lesões decorrentes de entorses, principalmente aquelas causadas por mecanismos de inversão. O teste também pode ser utilizado para comparar a mobilidade e estabilidade entre os dois tornozelos.', 'Paciente sentado ou em decúbito dorsal, com a perna relaxada. O examinador estabiliza a região distal da perna e segura o calcâneo. Em seguida, realiza uma inclinação do tálus, geralmente através de um movimento de inversão do pé. A quantidade de movimento, a presença de dor e a sensação de estabilidade são comparadas com o tornozelo contralateral.', 'O teste é considerado positivo quando há aumento excessivo da inclinação talar, sensação de instabilidade ou dor, principalmente quando comparado ao lado não lesionado. Esses achados podem indicar frouxidão ou lesão dos ligamentos laterais do tornozelo, especialmente do ligamento calcaneofibular.', NULL, NULL),
  (6, 'Quadril', 'Thomas', 'Flexores do quadril (iliopsoas)', 'Teste clínico utilizado para avaliar encurtamento ou contratura dos flexores do quadril, principalmente do iliopsoas, podendo também fornecer informações sobre o reto femoral e outras estruturas.', 'Identificar limitação da extensão do quadril causada por encurtamento dos músculos flexores do quadril.', '1. O paciente fica deitado de barriga para cima, próximo à borda da maca. 2. Uma das pernas é levada em direção ao peito e mantida nessa posição para estabilizar a pelve. 3. A outra perna permanece relaxada e é deixada descer em direção à maca. 4. O avaliador observa a posição da coxa e do joelho da perna testada.', 'O teste é positivo quando a coxa da perna testada não consegue permanecer apoiada na maca, ficando elevada, indicando possível encurtamento/contratura dos flexores do quadril. Se o joelho tende a estender enquanto a coxa permanece apoiada, pode haver participação do reto femoral.', NULL, NULL),
  (7, 'Quadril', 'FADIR', 'Quadril (impacto femoroacetabular e lábio)', 'O FADIR é um teste provocativo do quadril cujo nome vem de Flexão, Adução e Rotação Interna. É utilizado principalmente na investigação de impacto femoroacetabular (IFA) e alterações intra-articulares, como lesões labrais.', 'Avaliar se a combinação de movimentos de flexão, adução e rotação interna reproduz sintomas relacionados ao quadril, especialmente dor na região anterior ou na virilha.', '1. O paciente fica deitado de barriga para cima. 2. O avaliador flexiona o quadril e o joelho, geralmente até aproximadamente 90°. 3. Mantendo o quadril flexionado, realiza-se adução da coxa, levando o joelho em direção à linha média do corpo. 4. Em seguida, realiza-se rotação interna do quadril, podendo aplicar uma leve pressão no final do movimento.', 'É considerado positivo quando o teste reproduz a dor familiar do paciente, principalmente dor anterior no quadril ou na região da virilha. Também podem ocorrer sintomas como estalido, travamento ou sensação de impacto.', NULL, NULL),
  (8, 'Ombro', 'Neer', 'Manguito rotador (subacromial)', 'O teste baseia-se no impacto mecânico passivo. Ao elevar o braço do paciente em rotação interna, o tubérculo maior do úmero é forçado contra a borda anteroinferior do acrômio. Esse movimento comprime mecanicamente o tendão do supraespinhal e a bursa subacromial, reproduzindo a dor se houver inflamação ou lesão nessas estruturas.', 'Avaliar o impacto subacromial (atrito das estruturas sob o acrômio).', 'O fisioterapeuta estabiliza a escápula do paciente com uma das mãos. Com a outra mão, realiza a elevação passiva e forçada do braço em rotação interna e flexão anterior (levantando o braço estendido próximo à orelha).', 'O paciente sentir dor na região anterolateral do ombro durante a elevação, indicando compressão do tendão do supraespinhal ou da bursa subacromial.', NULL, NULL),
  (9, 'Ombro', 'Jobe', 'Supraespinhal', 'O teste baseia-se no isolamento anatômico e biomecânico do músculo supraespinhal. Ao posicionar o braço a 90° de abdução, 30° de flexão anterior (plano da escápula) e com rotação interna máxima ("polegar para baixo"), a ação dos músculos deltoide e bíceps é minimizada. Essa posição coloca a maior parte da carga resistida diretamente sobre o tendão do supraespinhal. Se ele estiver inflamado ou rompido, o paciente não conseguirá vencer a resistência física ou sentirá dor intensa.', 'Avaliar a integridade e força do tendão do músculo supraespinhal.', 'O paciente posiciona os braços em abdução de 90° no plano da escápula (cerca de 30° para a frente) e com os polegares apontados para o chão (rotação interna máxima). O fisioterapeuta aplica uma força para baixo nos braços do paciente, enquanto o paciente tenta resistir mantendo a posição.', 'O paciente manifestar dor ou fraqueza (incapacidade de resistir à força do examinador), sugerindo tendinopatia ou ruptura do supraespinhal.', NULL, NULL),
  (10, 'Cotovelo', 'Cozen', 'Extensores do punho (epicôndilo lateral)', 'O teste de Cozen é uma manobra clínica utilizada para avaliar a presença de epicondilalgia lateral (cotovelo de tenista). Baseia-se na reprodução da dor por meio da contração resistida dos músculos extensores do punho, especialmente aqueles que se originam no epicôndilo lateral do úmero.', 'Avaliar a presença de dor e possíveis alterações nos tendões extensores do punho, principalmente na região do epicôndilo lateral.', 'O paciente permanece sentado, com o cotovelo flexionado aproximadamente a 90° e o antebraço pronado. O fisioterapeuta estabiliza o cotovelo com uma das mãos. Com a outra mão, solicita que o paciente realize a extensão do punho contra resistência, podendo associar o desvio radial.', 'O paciente apresentar dor na região do epicôndilo lateral do cotovelo durante a extensão resistida do punho, sugerindo epicondilalgia lateral.', NULL, NULL),
  (11, 'Cotovelo', 'Estresse em Valgo', 'LCM do cotovelo', 'O teste de estresse em valgo é uma manobra clínica utilizada para avaliar a integridade do ligamento colateral medial (LCM) do cotovelo. Baseia-se na aplicação de uma força lateral sobre o antebraço, provocando uma abertura na região medial da articulação e tensionando o ligamento colateral medial.', 'Avaliar a estabilidade medial do cotovelo e identificar possíveis lesões ou frouxidão do ligamento colateral medial.', 'O paciente permanece sentado ou em pé, com o cotovelo levemente flexionado (aproximadamente 20° a 30°). O fisioterapeuta estabiliza a região lateral do cotovelo com uma das mãos. Com a outra mão, segura o antebraço e aplica uma força em valgo, direcionando-o lateralmente. Durante o movimento, observa a abertura articular e compara a resposta com o cotovelo contralateral.', 'O paciente apresentar dor na região medial do cotovelo, aumento da abertura articular ou frouxidão ligamentar em comparação ao lado oposto, sugerindo possível lesão do ligamento colateral medial.', NULL, NULL),
  (12, 'Punho', 'Tinel', 'Nervo mediano (túnel do carpo)', 'Teste de provocação neural realizado por meio de percussão sobre um nervo, procurando reproduzir sintomas relacionados à sua irritação ou compressão.', 'No punho, é utilizado principalmente para investigar compressão do nervo mediano no túnel do carpo.', 'Paciente mantém o antebraço e punho relaxados. O examinador localiza a região do túnel do carpo, na face palmar do punho. Realiza pequenas percussões sobre o trajeto do nervo mediano.', 'A percussão provoca ou reproduz: formigamento; parestesia; sensação de choque; eventualmente dor; principalmente irradiando para o território do nervo mediano.', NULL, NULL),
  (13, 'Punho', 'Phalen', 'Nervo mediano (túnel do carpo)', 'Teste provocativo utilizado principalmente para investigar síndrome do túnel do carpo, através da manutenção do punho em flexão.', 'Aumentar a pressão dentro do túnel do carpo e verificar se isso reproduz sintomas relacionados à compressão do nervo mediano.', 'Paciente coloca os punhos em flexão máxima. As faces dorsais das mãos ficam encostadas uma contra a outra. A posição é mantida, geralmente por aproximadamente 60 segundos. O examinador pergunta se surgiram ou aumentaram os sintomas.', 'Durante a posição, o paciente apresenta ou relata: formigamento; dormência; parestesia; dor; principalmente na distribuição do nervo mediano.', NULL, NULL),
  (14, 'Coluna lombar', 'Lasègue', 'Raízes lombossacrais', 'O teste de Lasègue, também chamado de Elevação da Perna Estendida, é um teste clínico utilizado para avaliar a presença de irritação ou compressão das raízes nervosas lombossacrais, principalmente em casos de ciatalgia e hérnia de disco lombar.', 'Verificar se o alongamento das estruturas neurais reproduz a dor irradiada para o membro inferior, auxiliando na investigação de radiculopatia lombar, como em casos de hérnia de disco.', 'Paciente em decúbito dorsal. O examinador eleva passivamente a perna com o joelho estendido, realizando flexão do quadril. O teste é considerado positivo quando surge dor irradiada característica, geralmente entre 30° e 70° de elevação.', 'Reprodução da dor irradiada, geralmente descendo pela parte posterior da perna, principalmente quando ocorre entre aproximadamente 30° e 70° de elevação.', 'graus', NULL),
  (15, 'Coluna lombar', 'Patrick-FABERE', 'Quadril e articulação sacroilíaca', 'O Teste de Patrick (também amplamente conhecido pelo acrônimo FABERE ou FABER) é uma manobra de avaliação ortopédica e fisioterapêutica usada para identificar disfunções na articulação do quadril ou na articulação sacroilíaca.', 'Verificar se os movimentos combinados provocam dor ou limitação, auxiliando na investigação de alterações no quadril ou na articulação sacroilíaca.', 'Paciente em decúbito dorsal. Coloca-se o membro testado em flexão, abdução e rotação externa, formando uma posição semelhante ao número 4. O examinador estabiliza a pelve e aplica uma pressão suave sobre o joelho e/ou membro. Dor ou limitação podem indicar alteração.', 'Reprodução de dor ou limitação, principalmente na região do quadril ou sacroilíaca.', NULL, NULL),
  (16, 'Tórax', 'Adams', 'Coluna (escoliose)', 'O Teste de Adams (ou teste de flexão anterior de Adams) é uma manobra clínica de triagem rápida e não invasiva utilizada para rastrear e avaliar a presença de escoliose (desvio lateral da coluna vertebral) em crianças, adolescentes e adultos.', 'Identificar alterações na simetria do tronco e observar a presença de gibosidade, que pode estar relacionada à rotação das vértebras.', 'Paciente em pé e depois realiza flexão anterior do tronco, deixando os braços soltos. O examinador observa o dorso por trás, procurando gibosidade/elevação de um lado do tórax. A presença de assimetria que persiste durante a flexão sugere escoliose estrutural.', 'Presença de assimetria ou gibosidade que se torna evidente durante a flexão anterior do tronco.', NULL, NULL),
  (17, 'Tórax', 'Wright', 'Desfiladeiro torácico (plexo braquial e vasos)', 'O Teste de Wright, também conhecido como teste de hiperabdução, é uma manobra clínica utilizada para investigar a Síndrome do Desfiladeiro Torácico, identificando possíveis compressões neurovasculares na região.', 'Avaliar possíveis compressões do plexo braquial e dos vasos sanguíneos durante a elevação do membro superior.', 'Paciente sentado ou em pé. O examinador realiza a abdução e rotação externa do ombro, elevando o braço acima da cabeça. Durante a manobra, observa alterações no pulso radial e o surgimento de sintomas.', 'Diminuição ou ausência do pulso radial e/ou reprodução de sintomas como dor, formigamento e dormência no membro superior.', NULL, NULL),
  (18, 'Coluna cervical', 'Spurling', 'Raízes cervicais', 'O Teste de Spurling é uma manobra clínica utilizada para investigar a presença de radiculopatia cervical, relacionada à compressão ou irritação das raízes nervosas cervicais.', 'Identificar possíveis compressões das raízes nervosas da coluna cervical.', 'Paciente sentado. O examinador posiciona a cabeça em extensão, inclinação lateral e rotação para o lado sintomático. Em seguida, aplica uma leve compressão axial sobre a cabeça.', 'Reprodução de dor irradiada, formigamento ou dormência que se estende do pescoço para o membro superior, indicando possível comprometimento radicular.', NULL, NULL),
  (19, 'Coluna cervical', 'Distração Cervical', 'Raízes cervicais', 'O Teste de Distração Cervical é uma manobra clínica utilizada para avaliar possíveis compressões das estruturas nervosas da coluna cervical por meio da tração da cabeça.', 'Verificar se a redução da pressão sobre as estruturas cervicais proporciona alívio dos sintomas relacionados à compressão das raízes nervosas.', 'Paciente em decúbito dorsal. O examinador posiciona as mãos na região occipital e mandibular do paciente e realiza uma tração suave da cabeça no sentido longitudinal, promovendo a separação das estruturas cervicais.', 'Diminuição ou alívio da dor irradiada e dos sintomas neurológicos no membro superior, sugerindo possível compressão radicular cervical.', NULL, NULL)
